SELECT ok(NOT has_table_privilege('authenticated', 'public.tenants', 'SELECT'), 'authenticated cannot read public.tenants');
SELECT ok(has_table_privilege('service_role', 'public.tenants', 'SELECT'), 'service_role can read public.tenants');
