-- 4. Stellr is tenant #1 and the platform owner; the 14+ rule holds for everyone else.
SELECT is(
  (SELECT slug || '|' || is_platform_owner::text || '|' || currency FROM public.tenants WHERE id = '00000000-0000-4000-8000-000000000001'),
  'stellr|true|usd',
  'Stellr is seeded with the fixed tenant id as platform owner'
);
SELECT is((SELECT derivation_mode FROM public.tenancy_settings), 'log', 'derivation starts in log mode');
SELECT ok((SELECT expand_applied_at IS NOT NULL AND expand_applied_at <= now() FROM public.tenancy_settings),
  'the expand migration stamped when it actually ran (the 7-day gate counts from here, not from its version date)');
SELECT ok(NOT EXISTS (
  SELECT 1 FROM pg_index i JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey)
  WHERE i.indrelid = 'public.tenancy_derivation_log'::regclass AND i.indisunique AND a.attname = 'day'
), 'the derivation log is append-only: no unique key per day, so no writer waits on a shared counter row');
SELECT ok((SELECT proconfig FROM pg_proc WHERE oid = 'public.tenancy_log_derivation(text, text, text, text)'::regprocedure) @> ARRAY['lock_timeout=250ms'],
  'the log writer caps any lock wait at 250 ms');
SELECT throws_ok(
  $q$INSERT INTO public.tenants (slug, legal_name, display_name, country, payment_region, currency, time_zone, min_participant_age)
     VALUES ('pgtap-young', 'Young Ltd', 'Young', 'AU', 'AU', 'aud', 'Australia/Sydney', 13)$q$,
  '23514', NULL, 'a tenant that is not the platform owner cannot admit under-14s'
);
SELECT throws_ok(
  $q$INSERT INTO public.tenants (slug, legal_name, display_name, country, payment_region, currency, time_zone)
     VALUES ('pgtap-mixed', 'Mixed Ltd', 'Mixed', 'AU', 'AU', 'usd', 'Australia/Sydney')$q$,
  '23514', NULL, 'an AU tenant cannot settle in USD'
);
SELECT throws_ok(
  $q$INSERT INTO public.tenants (slug, legal_name, display_name, country, payment_region, currency, time_zone, is_platform_owner)
     VALUES ('pgtap-owner2', 'Owner Two', 'Owner Two', 'US', 'US', 'usd', 'America/Denver', true)$q$,
  '23505', NULL, 'there is only one platform owner'
);
SELECT is(
  (SELECT tgenabled::text FROM pg_trigger WHERE tgrelid = 'public.survey_access_log'::regclass AND tgname = 'survey_access_log_append_only'),
  'O', 'the backfill left survey_access_log append-only'
);

-- 5. The trigger derives tenant_id from public.events, and in log mode never blocks.
INSERT INTO public.tenants (id, slug, legal_name, display_name, country, payment_region, currency, time_zone)
  VALUES ('11111111-1111-4111-8111-111111111111', 'pgtap-au', 'PgTap Pty Ltd', 'PgTap', 'AU', 'AU', 'aud', 'Australia/Sydney');
INSERT INTO public.events (tenant_id, slug, sanity_id, title, time_zone, country, currency, grade_system)
  VALUES ('11111111-1111-4111-8111-111111111111', 'pgtap-event', 'pgtap-sanity-id', 'PgTap Event', 'Australia/Sydney', 'AU', 'aud', 'au_years');
DELETE FROM public.tenancy_derivation_log;
INSERT INTO public.event_manager_assignments (clerk_user_id, event_slug) VALUES ('user_pgtap_1', 'pgtap-event');
SELECT is((SELECT tenant_id FROM public.event_manager_assignments WHERE clerk_user_id = 'user_pgtap_1'), '11111111-1111-4111-8111-111111111111'::uuid, 'log mode: tenant_id is derived from the event slug');
INSERT INTO public.event_manager_assignments (clerk_user_id, event_slug) VALUES ('user_pgtap_2', 'pgtap-no-such-event');
SELECT is((SELECT tenant_id FROM public.event_manager_assignments WHERE clerk_user_id = 'user_pgtap_2'), '00000000-0000-4000-8000-000000000001'::uuid, 'log mode: an unknown event slug falls back to Stellr and does not block');
SELECT is((SELECT COALESCE(sum(count), 0)::int FROM public.tenancy_derivation_log WHERE table_name = 'public.event_manager_assignments' AND reason = 'no_event'), 1, 'log mode: the unknown slug is counted as no_event');
INSERT INTO public.event_manager_assignments (clerk_user_id, event_slug, tenant_id) VALUES ('user_pgtap_3', 'pgtap-event', '00000000-0000-4000-8000-000000000001');
SELECT is((SELECT tenant_id FROM public.event_manager_assignments WHERE clerk_user_id = 'user_pgtap_3'), '11111111-1111-4111-8111-111111111111'::uuid, 'log mode: a supplied tenant_id that disagrees with the event is replaced by the derived one');
SELECT is((SELECT COALESCE(sum(count), 0)::int FROM public.tenancy_derivation_log WHERE table_name = 'public.event_manager_assignments' AND reason = 'mismatch'), 1, 'log mode: the disagreement is counted as mismatch');
UPDATE public.event_manager_assignments SET event_slug = 'pgtap-event' WHERE clerk_user_id = 'user_pgtap_2';
SELECT is((SELECT tenant_id FROM public.event_manager_assignments WHERE clerk_user_id = 'user_pgtap_2'), '11111111-1111-4111-8111-111111111111'::uuid, 'log mode: changing the event slug re-derives tenant_id');
INSERT INTO public.training_modules (title, event_ref) VALUES ('PgTap module', 'pgtap-sanity-id');
SELECT is((SELECT tenant_id FROM public.training_modules WHERE title = 'PgTap module'), '11111111-1111-4111-8111-111111111111'::uuid, 'log mode: tenant_id is derived from a Sanity event _id');
INSERT INTO public.training_modules (title) VALUES ('PgTap academy module');
SELECT is((SELECT tenant_id FROM public.training_modules WHERE title = 'PgTap academy module'), '00000000-0000-4000-8000-000000000001'::uuid, 'log mode: a row with no event key falls back to Stellr');
SELECT is((SELECT COALESCE(sum(count), 0)::int FROM public.tenancy_derivation_log WHERE table_name = 'public.training_modules' AND reason = 'no_key'), 1, 'log mode: the missing key is counted as no_key');
SELECT set_config('stellr.tenancy_backfill', 'on', true);
INSERT INTO public.event_manager_assignments (clerk_user_id, event_slug) VALUES ('user_pgtap_4', 'pgtap-no-such-event');
SELECT set_config('stellr.tenancy_backfill', '', true);
SELECT is((SELECT COALESCE(sum(count), 0)::int FROM public.tenancy_derivation_log WHERE table_name = 'public.event_manager_assignments' AND reason = 'no_event'), 1, 'backfill flag: writes during the backfill are not counted');
INSERT INTO public.event_manager_assignments (clerk_user_id, event_slug) VALUES ('user_pgtap_8', 'pgtap-no-such-event');
INSERT INTO public.event_manager_assignments (clerk_user_id, event_slug) VALUES ('user_pgtap_9', 'pgtap-no-such-event');
SELECT is((SELECT count(*)::int FROM public.tenancy_derivation_log WHERE table_name = 'public.event_manager_assignments' AND reason = 'no_event'), 3, 'log mode: each orphan write appends its own row (no shared counter row to lock)');
DELETE FROM public.tenancy_derivation_log;
SELECT count(*) FROM public.rename_event_slug('pgtap-event', 'pgtap-event-renamed');
SELECT is((SELECT tenant_id FROM public.event_manager_assignments WHERE clerk_user_id = 'user_pgtap_1'), '11111111-1111-4111-8111-111111111111'::uuid, 'slug rename before the mirror sync: the row keeps its tenant');
SELECT is((SELECT COALESCE(sum(count), 0)::int FROM public.tenancy_derivation_log WHERE reason IN ('no_key', 'no_event', 'mismatch', 'error')), 0, 'slug rename before the mirror sync: no orphan is counted (the 7-day window is not reset)');
SELECT ok((SELECT COALESCE(sum(count), 0)::int FROM public.tenancy_derivation_log WHERE table_name = 'public.event_manager_assignments' AND reason = 'kept') >= 1, 'slug rename before the mirror sync: counted as the informational reason kept');

UPDATE public.tenancy_settings SET derivation_mode = 'enforce';
SELECT throws_ok(
  $q$INSERT INTO public.event_manager_assignments (clerk_user_id, event_slug) VALUES ('user_pgtap_5', 'pgtap-no-such-event')$q$,
  '23503', NULL, 'enforce mode: an unknown event with no tenant_id is refused'
);
SELECT throws_ok(
  $q$INSERT INTO public.event_manager_assignments (clerk_user_id, event_slug, tenant_id)
     VALUES ('user_pgtap_6', 'pgtap-event', '00000000-0000-4000-8000-000000000001')$q$,
  '23514', NULL, 'enforce mode: a tenant_id that disagrees with the event is refused'
);
INSERT INTO public.event_manager_assignments (clerk_user_id, event_slug) VALUES ('user_pgtap_7', 'pgtap-event');
SELECT is((SELECT tenant_id FROM public.event_manager_assignments WHERE clerk_user_id = 'user_pgtap_7'), '11111111-1111-4111-8111-111111111111'::uuid, 'enforce mode: a known event still derives');
SELECT throws_ok(
  $q$INSERT INTO public.training_modules (title) VALUES ('PgTap keyless')$q$,
  '23502', NULL, 'enforce mode: no event key and no tenant_id is refused'
);
SELECT lives_ok(
  $q$SELECT * FROM public.rename_event_slug('pgtap-event-renamed', 'pgtap-event-renamed-2')$q$,
  'enforce mode: a slug rename that reaches rows before the mirror sync is not refused'
);
UPDATE public.tenancy_settings SET derivation_mode = 'log';

-- 6. The backfill (20261104140000) on rows that predate S3, then NOT NULL-readiness everywhere.
ALTER TABLE public.event_settings DISABLE TRIGGER zz_tenancy_derive_tenant_id;
ALTER TABLE public.survey_access_log DISABLE TRIGGER zz_tenancy_derive_tenant_id;
ALTER TABLE public.event_manager_assignments DISABLE TRIGGER zz_tenancy_derive_tenant_id;
ALTER TABLE public.training_modules DISABLE TRIGGER zz_tenancy_derive_tenant_id;
INSERT INTO public.event_settings (event_slug, updated_at) VALUES ('pgtap-historic', '2026-01-01T00:00:00Z');
INSERT INTO public.event_settings (event_slug, updated_at) VALUES ('pgtap-event', '2026-01-01T00:00:00Z');
INSERT INTO public.survey_access_log (actor, action, event_slug) VALUES ('staff', 'view', 'pgtap-historic');
INSERT INTO public.event_manager_assignments (clerk_user_id, event_slug) VALUES ('user_pgtap_hist', 'pgtap-event');
INSERT INTO public.training_modules (title) VALUES ('PgTap historic module');
ALTER TABLE public.event_settings ENABLE TRIGGER zz_tenancy_derive_tenant_id;
ALTER TABLE public.survey_access_log ENABLE TRIGGER zz_tenancy_derive_tenant_id;
ALTER TABLE public.event_manager_assignments ENABLE TRIGGER zz_tenancy_derive_tenant_id;
ALTER TABLE public.training_modules ENABLE TRIGGER zz_tenancy_derive_tenant_id;
DELETE FROM public.tenancy_derivation_log;
SELECT is((SELECT count(*)::int FROM public.event_settings WHERE event_slug IN ('pgtap-historic', 'pgtap-event') AND tenant_id IS NULL), 2, 'fixture: the pre-S3 rows start with a NULL tenant_id');
CREATE TEMP TABLE pgtap_backfill ON COMMIT DROP AS SELECT * FROM public.tenancy_backfill_tenant_ids();
SELECT is((SELECT count(*)::int FROM public.event_settings WHERE event_slug IN ('pgtap-historic', 'pgtap-event') AND tenant_id IS NULL), 0, 'backfill: the NULL rows now carry a tenant');
SELECT set_eq('SELECT tbl FROM pgtap_backfill', ARRAY[
    'agreements',
    'community_resources',
    'community_spaces',
    'credentials',
    'event_award_assignments',
    'event_badge_templates',
    'event_certificate_templates',
    'event_companies',
    'event_email_sends',
    'event_emails',
    'event_manager_assignments',
    'event_participations',
    'event_refunds',
    'event_settings',
    'event_store_offerings',
    'group_invoices',
    'group_join_tokens',
    'member_groups',
    'mentoring_cohorts',
    'merch_batches',
    'refund_policies',
    'registrations',
    'scholarship_applications',
    'store_event_discounts',
    'store_orders',
    'survey_access_log',
    'survey_distributions',
    'survey_responses',
    'team_profiles',
    'training_assignments',
    'training_modules',
    'volunteer_event_interest'
  ]::text[], 'the backfill finds every derived table from its trigger');
SELECT is((SELECT rows_updated FROM pgtap_backfill WHERE tbl = 'event_settings'), 2::bigint, 'the backfill updated both NULL event_settings rows');
SELECT is((SELECT tenant_id FROM public.event_settings WHERE event_slug = 'pgtap-historic'), '00000000-0000-4000-8000-000000000001'::uuid, 'backfill: an event the mirror does not know gets Stellr');
SELECT is((SELECT tenant_id FROM public.event_settings WHERE event_slug = 'pgtap-event'), '11111111-1111-4111-8111-111111111111'::uuid, 'backfill: an event the mirror knows gets its tenant');
SELECT is((SELECT updated_at FROM public.event_settings WHERE event_slug = 'pgtap-historic'), '2026-01-01T00:00:00Z'::timestamptz, 'backfill: updated_at is untouched');
SELECT is((SELECT tenant_id FROM public.survey_access_log WHERE event_slug = 'pgtap-historic'), '00000000-0000-4000-8000-000000000001'::uuid, 'backfill: the append-only survey_access_log is backfilled');
SELECT is((SELECT tenant_id FROM public.event_manager_assignments WHERE clerk_user_id = 'user_pgtap_hist'), '11111111-1111-4111-8111-111111111111'::uuid, 'backfill: an event_slug row takes the mirror event tenant');
SELECT is((SELECT tenant_id FROM public.training_modules WHERE title = 'PgTap historic module'), '00000000-0000-4000-8000-000000000001'::uuid, 'backfill: a row with no event key gets Stellr');
SELECT is((SELECT count(*)::int FROM public.tenancy_derivation_log), 0, 'backfill: nothing is logged (the orphan window is not swamped)');
SELECT is((SELECT string_agg(DISTINCT tgenabled::text, '') FROM pg_trigger
  WHERE tgname = 'zz_tenancy_derive_tenant_id' AND tgrelid IN ('public.event_settings'::regclass, 'public.survey_access_log'::regclass, 'public.event_manager_assignments'::regclass, 'public.training_modules'::regclass)),
  'O', 'backfill: the derivation triggers are enabled again');
SELECT throws_ok($q$UPDATE public.survey_access_log SET actor = 'x' WHERE event_slug = 'pgtap-historic'$q$,
  NULL, NULL, 'backfill: survey_access_log still refuses updates afterwards');
SELECT is((SELECT COALESCE(sum(rows_updated), 0)::int FROM public.tenancy_backfill_tenant_ids()), 0, 'backfill: re-running it changes nothing');
